def adjunction : generation proofs proofInitial ⊣ inclusion proofs :=
  Adjunction.mkOfHomEquiv {
    homEquiv := homEquiv proofs proofInitial
    homEquiv_naturality_left_symm := fun _ _ => Subsingleton.elim _ _
    homEquiv_naturality_right := fun _ _ => Subsingleton.elim _ _ }

def presentationAdjunction :
    presentationGeneration proofs proofInitial ⊣ presentationInclusion proofs :=
  Adjunction.mkOfHomEquiv {
    homEquiv := presentationHomEquiv proofs proofInitial
    homEquiv_naturality_left_symm := fun _ _ => Subsingleton.elim _ _
    homEquiv_naturality_right := fun _ _ => presentation_hom_ext proofs _ _ }

def adjunction : σ.pushforward ⊣ σ.inverseImage :=
  Adjunction.mkOfHomEquiv {
    homEquiv := σ.homEquiv
    homEquiv_naturality_left_symm := fun _ _ => Subsingleton.elim _ _
    homEquiv_naturality_right := fun _ _ => Subsingleton.elim _ _ }

def adjunction : generation (D := D) (V := V) ⊣ inclusion :=
  Adjunction.mkOfHomEquiv {
    homEquiv := homEquiv
    homEquiv_naturality_left_symm := fun _ _ => by
      apply ObjectProperty.hom_ext
      apply Hom.ext
      rfl
    homEquiv_naturality_right := fun _ _ => Hom.ext rfl }

def restrictedAdjunction : theoryFunctor G P Q σ ⊣
    restrictedRight G regularEpis P Q σ proofMap proofConclusion R hR :=
  Adjunction.mkOfHomEquiv {
    homEquiv := fun _A B => {
      toFun := fun f => homOfLE ((hR.gc _ _).mp
        ((FirstOrderReflection.generated_le_iff Q.proofs Q.initial _ B).mp (leOfHom f)))
      invFun := fun f => homOfLE ((FirstOrderReflection.generated_le_iff Q.proofs Q.initial _ B).mpr
        ((hR.gc _ _).mpr (leOfHom f)))
      left_inv := fun _ => Subsingleton.elim _ _
      right_inv := fun _ => Subsingleton.elim _ _ }
    homEquiv_naturality_left_symm := fun _ _ => Subsingleton.elim _ _
    homEquiv_naturality_right := fun _ _ => Subsingleton.elim _ _ }

def orderAdjunction : DeductionComparison.imageFunctor G σ ⊣ rightOrder adj σ :=
  Adjunction.mkOfHomEquiv {
    homEquiv := fun A B => {
      toFun := fun f => homOfLE ((order_galois adj σ A B).mp (leOfHom f))
      invFun := fun f => homOfLE ((order_galois adj σ A B).mpr (leOfHom f))
      left_inv := fun _ => Subsingleton.elim _ _
      right_inv := fun _ => Subsingleton.elim _ _ }
    homEquiv_naturality_left_symm := fun _ _ => Subsingleton.elim _ _
    homEquiv_naturality_right := fun _ _ => Subsingleton.elim _ _ }

theorem productLaws (T : SplitObject R) :
    @PCategory (FullCategory T) inferInstance (productData T) :=
  (restrictionProducts T).pcategoryLaws

theorem prodominical (T : SplitObject R) :
    @Prodominical (FullCategory T) inferInstance (productData T) inferInstance :=
  (restrictionProducts T).prodominicalLaws

def leftAdjunction : postcompose i ⊣ reindex i inverses :=
  Adjunction.mkOfHomEquiv {
    homEquiv := leftHomEquiv i inverses
    homEquiv_naturality_left_symm := left_naturality_left i inverses
    homEquiv_naturality_right := left_naturality_right i inverses
  }

def rightAdjunction : reindex i inverses ⊣ postcompose i :=
  Adjunction.mkOfHomEquiv {
    homEquiv := rightHomEquiv i inverses
    homEquiv_naturality_left_symm := right_naturality_left i inverses
    homEquiv_naturality_right := right_naturality_right i inverses
  }

def evaluationTheory (W : FirstOrderReflection.Theory Q) : P.Theories :=
  ⟨SliceSubobjectPredicates.evaluate point hZ W.val, evaluate_closed P U Q hQ point hZ W⟩

include hQ point hZ in

def derivationInitial : IsInitial (derivationAlgebra T R) :=
  SuccessCarrier.rawInitial (validatorFold T R).f R.inference (chosenAlgebra T R).str
    (chosenInitial T R)

def totalDerivationInitial : IsInitial (totalDerivationAlgebra T R) :=
  SuccessTransport.initial T (totalValidatorFold T R).f R.inference (totalChosenAlgebra T R).str
    (totalChosenInitial T R)

def proofInitial {A : PredicateCategory T} (axioms : A ⟶ (S).sentenceObject) :
    IsInitial (proofAlgebra T V σ π d axioms) :=
  SyntacticDerivation.derivationInitial T ((S).logicalRules axioms)

def fiberInitial (AxPA : Carrier) (e : ℕ) : IsInitial (fiberAlgebra AxPA e) :=
  (ArithmeticIndexedFibers.fiberInitial AxPA e).ofIso
    (carriedIso (ArithmeticIndexedFibers.fiberAlgebra AxPA e) (fiberOverIso AxPA e)).symm

def classicalTotalEquivalence :
    Object ≌ WideSubcategory (isTotal (C := SplitObject ClassicalPrograms.Rec)) :=
  equivalence.trans EnumerableCarriers.inclusion_rst.totalEquivalence

def monoInverse {C D : Object} (m : C ⟶ D) [Mono m] :
    splitComparison.obj D ⟶ splitComparison.obj C :=
  EnumerableCarriers.inclusion.map (PartialSpans.inverse (comparison.map m))

def coefficientIso (C : NumericalTuples.Object) :
    NumericalSyntax.predicateEquivalence.functor.obj (codedPredicate C) ≅ C :=
  predicatePresentationIso (codedPredicate C) ≪≫ codedObjectIso C

def mappedDerivationInitial :
    IsInitial (mappedAlgebra R (SyntacticDerivation.derivationAlgebra 𝗣𝗔 R)) :=
  (NumericalDerivation.codeInitial (interpretedRules R)).ofIso (interpretationAlgebraIso R)

def rho0 (Γ : Carrier) : (Rules.rules Γ).instances 0 ≅ (K).obj ((Rules.originalRules Γ).instances 0) :=
  copairedIso (A := (S₀).logicalParameters) (B := ArithmeticLiteralModel.axiomObject Γ)
    logicalIso (Iso.refl (Rules.axiomObject Γ))

def positiveSupport : (P).a.left ⟶ (K).algebra.carrier :=
  DerivationFiniteSupport.collect R K P (SyntacticDerivation.derivationInitial T R)
    (positiveLeafAssignment T L A B)

def orderIso (X : C) : Subobject X ≃o Subobject (E.functor.obj X) :=
  {
    toEquiv := Equiv.ofBijective (FiniteLimitSubobjects.object E.functor) ⟨
      (by intro A B h; exact le_antisymm (reflect_le E A B h.le) (reflect_le E B A h.ge)),
      object_surjective E X⟩
    map_rel_iff' := by
      intro A B
      exact ⟨reflect_le E A B, fun h => FiniteLimitSubobjects.object_monotone E.functor h⟩ }

omit [Regular D] in

def syntaxInitial : IsInitial (syntaxAlgebra F) :=
  ForwardSyntaxTransport.castInitial _ _ _
    (ForwardSyntaxTransport.initial (E) p q (S).algebra (S).initial)

def initial : IsInitial (algebra T R) :=
  SliceInference.initial R _
    (SyntacticDerivation.totalDerivationInitial T (SliceRuleObjects.rules R))

def initial (P : TotalSplit 𝗣𝗔)
    (A : Subobject ((constantFamilyFunctor P).obj ((G).obj (S).sentenceObject))) :
    IsInitial (proofs P A) := SyntacticSliceDerivations.initial 𝗣𝗔 (rules P A)

def wordInitial (p q : SyntaxPolynomial (Total.TotalCategory P)) : IsInitial (wordAlgebra p q) :=
  SyntacticSyntax.initialOfTerminalParameters p q (wordAlgebra p q)
    (wordWithParametersInitial (⊤_ (Total.TotalCategory P)) p q)

def wordWithParametersInitial :
    IsInitial (SyntaxPolynomial.algebraWithParameters p q (wordAlgebra p q) R) :=
  (explicitWordInitial R p q).ofIso (parameterWordAlgebraIso R p q)

def canonicalCategoricalSyntax (z : Point) (V : Total.CanonicalTotal z)
    (σ π : ℕ → Total.CanonicalTotal z) (d : ℕ) : CategoricalSyntax V σ π d :=
  mappedCategoricalSyntax (Total.pointPresentation z) V σ π d

def proofInitial {A : Total.CanonicalTotal z} (axioms : A ⟶ (S).sentenceObject) :
    IsInitial (proofAlgebra z V σ π d axioms) :=
  Derivation.Canonical.derivationInitial z ((S).logicalRules axioms)

def printedRules (A : Subobject (P ⨯ S.sentenceObject)) :
    RulePresentation (P ⨯ S.algebra.a.2) 2 :=
  SliceRuleObjects.rules (rules z S P (axiomArrow z S P A))

def printedInitial (A : Subobject (P ⨯ S.sentenceObject)) :
    IsInitial (printedAlgebra z S P A) :=
  Derivation.Canonical.derivationInitial z (printedRules z S P A)

def optionEquiv : Option Fm ≃ (U).obj (OptionSyntax.obj (S).algebra.a.2) :=
  Equiv.ofBijective (optionPoint P σ π d)
    ⟨optionPoint_injective P σ π d,optionPoint_surjective P σ π d⟩

def equalitySchemeIso : (E).functor.obj (S₁).equalitySchemeParameters ≅ (S₂).equalitySchemeParameters :=
  pullbackChart (E) (equalityFirstIso a V σ π d) (equalitySecondIso a V σ π d)
    (equalityBaseIso a V σ π d) _ _ _ _ (equalityFirst_fst a V σ π d) (equalitySecond_fst a V σ π d)

def mappedInitial (A : Endofunctor.Algebra R.inference) (hA : IsInitial A) :
    IsInitial (mappedAlgebra E iF R R' h A) :=
  AlgebraTransport.initial (slice E iF) (comparison E iF R R' h) A hA

def turingData := NativeSplitSlices.turingData (ρ := Uniform.nativeRestriction)
  (source_restriction_eq a) (inverses a) (U.val : Total.CanonicalTotal a)
    (Uniform.recursionCategory a)

def printedInitial (a b : Idem EffectiveFork.V) : IsInitial (printedAlgebra a b) :=
  AlgebraTransport.initial (CategoryTheory.Equivalence.refl (C := Over sentenceObject))
    (printedComparison a b) (inferenceAlgebra a b) (inferenceInitial a b)

def shapedInitial (a b : Idem EffectiveFork.V) : IsInitial (shapedAlgebra a b) :=
  AlgebraTransport.initial (CategoryTheory.Equivalence.refl (C := Over sentences))
    (shapedComparison a b) (printedAlgebra a b) (printedInitial a b)

def initial : IsInitial (algebra N D P) :=
  IsInitial.ofUniqueHom (fold N D P) (by
    intro B m
    apply Endofunctor.Algebra.Hom.ext
    let t : pairAlgebra N D P ⟶ targetPair N D P B := {
      f := (terminal.from _, m.f)
      h := Prod.ext (terminalIsTerminal.hom_ext _ _) m.h }
    exact congrArg (fun k => k.f.2) ((ForkFirstOrderFormula.pairStable N D P).hom_ext
      t ((ForkFirstOrderFormula.pairStable N D P).to (targetPair N D P B))))

def fold (B : Endofunctor.Algebra (polynomial D P)) :
    ForkParameterizedFormulaFolds.parameterCarrier D P ⟶ B.a :=
  (ForkParameterizedFormulaFolds.fold D P (target D P B)).f

def constantFold (B : Endofunctor.Algebra (polynomial D P)) :
    constantFamily P (ForkFirstOrderFormula.algebra D).a ⟶ B.a :=
  (ForkParameterizedFormulaFolds.parameterCarrierIso D P).inv ≫ fold D P B

def printedStatement (A : Subobject (P ⨯ (S).sentenceObject)) :
    Σ B : Endofunctor.Algebra (printedRules D P A).inference, IsInitial B :=
  ⟨printedAlgebra D P A, printedInitial D P A⟩

def formulaExpression (V : D) (π : ℕ → D) (d : ℕ) : SyntaxPolynomial D :=
  .sum (.sum (.sum (.sum (power .term 2) (constructors π d)) .formula)
    (power .formula 2)) (.product (.coefficient V) .formula)

def formulaSubstitutionOption :
    S.algebra.a.2 ⨯ S.substitutionParameters ⟶ OptionSyntax.obj S.algebra.a.2 :=
  (prod.braiding _ _).hom ≫ S.substitutionFold.2.left ≫ prod.snd ≫ prod.snd
